cd /Users/jim/src/apps/specification_methodology/stdo_representation/dogfood/t009-frame-projection/native-qualification/fp04-run-004/claude-projection/snapshot && python3 - <<'EOF'
import json,hashlib,os
snap=json.load(open('SNAPSHOT_INPUTS.json'))
bad=0
for rel,exp in snap['files'].items():
    h=hashlib.sha256(open(rel,'rb').read()).hexdigest()
    if h!=exp: bad+=1; print("MISMATCH",rel,h)
print("checked",len(snap['files']),"files; mismatches:",bad)
# aggregate of 52 source members per source-manifest
m=json.load(open('stdo_representation/dogfood/t009-frame-projection/run-001/source/source-manifest.json'))
print("manifest keys:",list(m.keys()))
for k,v in m.items():
    if not isinstance(v,(list,dict)): print(" ",k,"=",v)
members = m.get('members') or m.get('files')
if isinstance(members,dict): items=sorted(members.items())
else: items=[(x.get('path'),x.get('sha256')) for x in members]
print("member count",len(items))
root='stdo_representation/dogfood/t009-frame-projection/run-001/source'
mm=0; agg=hashlib.sha256()
for p,s in items:
    fp=os.path.join(root,p)
    if os.path.exists(fp):
        h=hashlib.sha256(open(fp,'rb').read()).hexdigest()
        if h!=s: mm+=1; print(" member mismatch",p)
    else: print(" member absent (excluded?)",p)
    agg.update(f"{p} {s}\n".encode())
print("member mismatches",mm,"; naive aggregate",agg.hexdigest())
EOF

